create extension if not exists pgcrypto;
create type user_role as enum('teacher','student'); create type publication_status as enum('draft','published'); create type purchase_status as enum('pending','paid','failed','refunded');
create table users(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text not null,role user_role not null default 'student',active boolean not null default true,display_name text not null,created_at timestamptz not null default now(),check(email=lower(email)));
-- Teacher creation is DBA-only. There is intentionally no registration endpoint.
create table courses(id uuid primary key default gen_random_uuid(),title text not null,class_name text not null,published boolean not null default false,created_at timestamptz not null default now());
create table enrollments(student_id uuid references users,course_id uuid references courses,active boolean not null default true,primary key(student_id,course_id));
create table study_materials(id uuid primary key,teacher_id uuid not null references users,title text not null,description text not null default '',subject text not null,class_name text not null,course_id uuid references courses,chapter text not null default '',topic text not null default '',academic_session text not null default '',language text not null check(language in('hi','en','hinglish')),file_key text not null,thumbnail_key text,author text not null,tags text[] not null default '{}',is_paid boolean not null default false,price_paise int not null default 0 check(price_paise>=0),status publication_status not null default 'draft',featured boolean not null default false,download_allowed boolean not null default false,expires_at timestamptz,sort_order int not null default 0,version int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,check(not is_paid or price_paise>0)); create index materials_listing on study_materials(status,class_name,subject) where deleted_at is null;
create table purchases(id uuid primary key default gen_random_uuid(),student_id uuid not null references users,material_id uuid not null references study_materials,provider text not null,provider_order_id text unique not null,provider_payment_id text unique,status purchase_status not null default 'pending',amount_paise int not null,receipt text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create unique index one_active_purchase on purchases(student_id,material_id) where status='paid';
create table payment_transactions(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references purchases,event_id text unique not null,event_type text not null,verified boolean not null,payload jsonb not null,created_at timestamptz not null default now());
create table download_logs(id bigint generated always as identity primary key,user_id uuid references users,material_id uuid references study_materials,created_at timestamptz not null default now());
create table audit_logs(id bigint generated always as identity primary key,actor_id uuid references users,action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
-- Additional bounded contexts are introduced by later migrations: videos/live, exams, assignments and notifications.
